func TestVersionCommand(t *testing.T) {
	jsonOutput = false
	t.Cleanup(func() { jsonOutput = false })
	rootCmd.SetArgs([]string{"version"})
	out := captureStdout(t, func() {
		err := rootCmd.Execute()
		require.NoError(t, err)
	})
	// Compare against resolveVersion(), not the raw `version` var: `version`
	// is empty unless the Makefile's ldflags set it (main.go, ethos-vqbk),
	// and `assert.Contains(out, "")` would pass vacuously and prove nothing.
	assert.Contains(t, out, resolveVersion())
}

func TestVersionCommandJSON(t *testing.T) {
	jsonOutput = false
	t.Cleanup(func() { jsonOutput = false })
	rootCmd.SetArgs([]string{"version", "--json"})
	out := captureStdout(t, func() {
		err := rootCmd.Execute()
		require.NoError(t, err)
	})
	assert.True(t, jsonOutput, "--json flag should set jsonOutput")
	var parsed map[string]string
	err := json.Unmarshal([]byte(out), &parsed)
	require.NoError(t, err, "output should be valid JSON")
	assert.Equal(t, resolveVersion(), parsed["version"])
}

// TestResolveVersion_LdflagsSet asserts the ldflags-injected version wins
// outright, even when it looks nothing like a build-info module version —
// resolveVersion must never second-guess what the Makefile computed.
func TestResolveVersion_LdflagsSet(t *testing.T) {
	old := version
	version = "v9.9.9-custom"
	t.Cleanup(func() { version = old })

	assert.Equal(t, "v9.9.9-custom", resolveVersion())
}

// TestResolveVersion_FallsBackToBuildInfo asserts that when ldflags left
// `version` at its zero value, resolveVersion reports something — the
// runtime/debug.BuildInfo path (ethos-vqbk) — rather than silently
// returning empty. The `go test` binary's own build info is exercised
// here (see TestResolveVersion_DevelNormalizedToDev for what shape that
// takes today); this test only pins the "never empty" contract, which
// holds regardless of what Go's build-info stamping does release to
// release.
func TestResolveVersion_FallsBackToBuildInfo(t *testing.T) {
	old := version
	version = ""
	t.Cleanup(func() { version = old })

	got := resolveVersion()
	assert.NotEmpty(t, got, "resolveVersion must never return empty")
}

// TestResolveVersion_DevelNormalizedToDev pins the documented mapping from
// the runtime/debug sentinel "(devel)" to this command's own "dev"
// convention. `go test` compiles this package as its own main module with
// no requested version, so runtime/debug.ReadBuildInfo().Main.Version is
// "(devel)" here whenever the toolchain has no VCS info to derive a
// pseudo-version from (e.g. -buildvcs=false, or a checkout with no .git) —
// this test exercises resolveVersion's own normalization step directly,
// rather than depending on that toolchain-and-checkout-dependent condition.
func TestResolveVersion_DevelNormalizedToDev(t *testing.T) {
	old := version
	version = ""
	t.Cleanup(func() { version = old })

	info, ok := debug.ReadBuildInfo()
	require.True(t, ok, "go test binaries always have build info")
	if info.Main.Version != "(devel)" {
		t.Skipf("this checkout's build info reports Main.Version=%q, not the "+
			"\"(devel)\" sentinel this test targets — likely VCS-derived "+
			"stamping from a real git checkout (see TestResolveVersion_FallsBackToBuildInfo)",
			info.Main.Version)
	}
	assert.Equal(t, "dev", resolveVersion())
}

