	if interval <= 0 {
		interval = DefaultPruneInterval
	}

	stop := make(chan struct{})
	s.pruneStop = stop
	s.pruneWG.Add(1)
	go func() {
		defer s.pruneWG.Done()
		s.pruneTick(maxAge)
		ticker := time.NewTicker(interval)
		defer ticker.Stop()
		for {
			select {
